-- Columns dropped from brz_orders:
--   o_comment                    free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)
-- Columns replaced (not lost):
--   o_orderpriority  -> order_priority_rank + order_priority
--   o_orderstatus    -> order_status (decoded)
--   o_clerk          -> clerk_id

with source as (
    {{ deduplicate(ref('brz_orders'), partition_by=['o_orderkey']) }}
)

select
    -- keys
    o_orderkey::varchar                                        as order_id,
    o_custkey::varchar                                         as customer_id,
    -- 'Clerk#000000951' -> '951'
    ltrim(split_part(o_clerk, '#', 2), '0')::varchar           as clerk_id,

    -- attributes
    case o_orderstatus
        when 'F' then 'Fulfilled'
        when 'O' then 'Open'
        when 'P' then 'Partially fulfilled'
    end::varchar                                               as order_status,
    o_orderdate::date                                          as order_date,
    -- '1-URGENT' -> rank 1 / label 'Urgent'
    split_part(o_orderpriority, '-', 1)::number(38, 0)         as order_priority_rank,
    {{ clean_label("split_part(o_orderpriority, '-', 2)") }}::varchar as order_priority,
    o_shippriority::number(38, 0)                              as ship_priority,

    -- measures
    o_totalprice::number(12, 2)                                as order_total_price,

    _loaded_at
from source
